set-variable.value:
@{
    var token = (Jwt)context.Variables["parsedJwt"];
    if (token.Issuer != "{{caller-entra-issuer}}" || token.Audiences.Count() != 1
        || token.Audiences.First() != "{{api-audience}}" || !token.ExpirationTime.HasValue
        || token.ExpirationTime.Value <= context.Timestamp
        || (token.NotBefore.HasValue && token.NotBefore.Value > context.Timestamp)) { return false; }
    var claims = token.Claims;
    foreach (var name in new[] { "tid", "oid", "azp", "scp", "ver" }) {
      if (!claims.ContainsKey(name) || claims[name] == null || claims[name].Length != 1
          || string.IsNullOrWhiteSpace(claims[name][0])) { return false; }
    }
    Guid tenant;
    Guid subject;
    Guid client;
    Guid configuredTenant;
    if (!Guid.TryParse(claims["tid"][0], out tenant) || tenant == Guid.Empty
        || !Guid.TryParse("{{caller-entra-tenant-id}}", out configuredTenant) || tenant != configuredTenant
        || !Guid.TryParse(claims["oid"][0], out subject) || subject == Guid.Empty
        || !Guid.TryParse(claims["azp"][0], out client) || client == Guid.Empty
        || client.ToString().Equals("{{api-audience}}", StringComparison.OrdinalIgnoreCase)
        || claims["ver"][0] != "2.0"
        || !claims["scp"][0].Split(' ').Contains("{{required-scope}}")) { return false; }
    if (claims.ContainsKey("idtyp") && (claims["idtyp"] == null || claims["idtyp"].Length != 1
        || claims["idtyp"][0] != "user")) { return false; }
    var clients = "{{caller-entra-client-ids}}";
    return clients == "__any__" || clients.Split(',').Any(allowed => allowed.Trim().Equals(client.ToString(), StringComparison.OrdinalIgnoreCase));
  }

@{
    var claims = ((Jwt)context.Variables["parsedJwt"]).Claims;
    foreach (var name in new[] { "preferred_username", "upn" }) {
      if (claims.ContainsKey(name) && claims[name] != null && claims[name].Length == 1
          && !string.IsNullOrWhiteSpace(claims[name][0])) { return claims[name][0]; }
    }
    return (string)context.Variables["callerSubject"];
  }
